// Expected PromQL strings were generated by running the portal's own builders (cloud-portal
// app/features/edge/proxy/metrics/queries.ts and the Active POPs card's buildRateQuery /
// buildHistogramQuantileQuery calls in overview/active-pops-card.tsx) with the same inputs.
import type { PromResponse } from '..';
import {
  albRegionalLatencyQuantileQuery,
  albRegionalRpsQuery,
  albRegionalServerErrorRpsQuery,
  albWafIncreaseQuery,
  albWafTopRulesQuery,
  categoryFromFile,
  WAF_BLOCKED_LABELS,
  wafTopRulesView,
} from '..';

const scope = { projectId: 'proj-a', proxyId: 'gw-1' };
const TRAFFIC =
  '{resourcemanager_datumapis_com_project_name="proj-a",gateway_name="gw-1",gateway_namespace="default",label_topology_kubernetes_io_region!=""}';
const WAF = '{resourcemanager_datumapis_com_project_name="proj-a",gateway_name="gw-1",label_topology_kubernetes_io_region!=""}';

describe('KPI strip PromQL (portal metrics-strip parity)', () => {
  test('WAF blocked: blocked + dropped, no gateway_namespace, reset-guarded', () => {
    const sel =
      '{resourcemanager_datumapis_com_project_name="proj-a",gateway_name="gw-1",label_topology_kubernetes_io_region!="",coraza_outcome=~"blocked|dropped"}';
    expect(albWafIncreaseQuery({ ...scope, customLabels: WAF_BLOCKED_LABELS }, '1h')).toBe(
      `sum((increase(coraza_envoy_filter_request_events_total${sel}[1h]) * (resets(coraza_envoy_filter_request_events_total${sel}[1h]) == bool 0)))`
    );
  });
});

describe('Active regions PromQL (portal active-pops-card parity)', () => {
  test('requests per second by region over 5m', () => {
    expect(albRegionalRpsQuery(scope, '5m')).toBe(
      `sum(rate(envoy_vhost_vcluster_upstream_rq${TRAFFIC}[5m])) by (label_topology_kubernetes_io_region)`
    );
  });

  test('5xx (not 4xx) per second by region', () => {
    expect(albRegionalServerErrorRpsQuery(scope, '5m')).toBe(
      'sum(rate(envoy_vhost_vcluster_upstream_rq{resourcemanager_datumapis_com_project_name="proj-a",gateway_name="gw-1",gateway_namespace="default",label_topology_kubernetes_io_region!="",envoy_response_code=~"5.."}[5m])) by (label_topology_kubernetes_io_region)'
    );
  });

  test('p95 by region', () => {
    expect(albRegionalLatencyQuantileQuery(0.95, scope, '5m')).toBe(
      `histogram_quantile(0.95, sum(rate(envoy_vhost_vcluster_upstream_rq_time_bucket${TRAFFIC}[5m])) by (le,label_topology_kubernetes_io_region))`
    );
  });
});

describe('Top WAF rules', () => {
  test('PromQL (portal albWafTopRulesQuery parity)', () => {
    const guarded = `(increase(coraza_envoy_filter_request_events_total${WAF}[1m]) * (resets(coraza_envoy_filter_request_events_total${WAF}[1m]) == bool 0))`;
    expect(albWafTopRulesQuery(scope, '1h')).toBe(
      'topk(20, sum by (coraza_rule_id, coraza_rule_file, coraza_interruption_phase, coraza_rule_severity, coraza_rule_action, coraza_rule_version) ' +
        `(sum_over_time(${guarded}[1h:1m])))`
    );
  });

  test('categories from CRS file names', () => {
    expect(categoryFromFile('REQUEST-942-APPLICATION-ATTACK-SQLI.conf')).toBe('Sqli');
    expect(categoryFromFile('REQUEST-920-PROTOCOL-ENFORCEMENT.conf')).toBe('Protocol Enforcement');
    expect(categoryFromFile('@owasp_crs/recommended.conf')).toBe('Recommended');
    expect(categoryFromFile('@custom_rules.conf')).toBe('Custom Rules');
    expect(categoryFromFile(null)).toBeNull();
  });

  test('merges slices per rule, drops the rule-less series, ranks by events', () => {
    // Shape from the staging gateway: the allowed traffic comes back as `{}`.
    const response: PromResponse = {
      status: 'success',
      data: {
        resultType: 'vector',
        result: [
          { metric: {}, value: [1791987255, '22404'] },
          {
            metric: { coraza_interruption_phase: 'response_body', coraza_rule_action: 'deny', coraza_rule_id: '959100' },
            value: [1791987255, '16'],
          },
          {
            metric: {
              coraza_rule_id: '942100',
              coraza_rule_file: 'REQUEST-942-APPLICATION-ATTACK-SQLI.conf',
              coraza_interruption_phase: 'request_headers',
              coraza_rule_severity: 'critical',
              coraza_rule_action: 'deny',
              coraza_rule_version: 'OWASP_CRS/4.7.0',
            },
            value: [1791987255, '30'],
          },
          {
            metric: { coraza_rule_id: '942100', coraza_interruption_phase: 'request_body', coraza_rule_action: 'drop' },
            value: [1791987255, '10'],
          },
          { metric: { coraza_rule_id: '123456' }, value: [1791987255, '0'] },
          { metric: { coraza_rule_id: '920350' }, value: [1791987255, 'NaN'] },
        ],
      },
    };
    const rows = wafTopRulesView(response);
    expect(rows.map((r) => [r.ruleId, r.events])).toEqual([
      ['942100', 40],
      ['959100', 16],
    ]);
    expect(rows[0]).toMatchObject({
      name: 'SQL Injection via libinjection',
      category: 'Sqli',
      phases: ['Request Headers', 'Request Body'],
      severities: ['critical'],
      actions: ['deny', 'drop'],
      version: 'OWASP_CRS/4.7.0',
    });
    expect(rows[0].share).toBeCloseTo(40 / 56);
    expect(rows[1]).toMatchObject({ name: 'Outbound Anomaly Score Exceeded', category: null, phases: ['Response Body'] });
    expect(wafTopRulesView(undefined)).toEqual([]);
  });

  test('unknown rules get a generic name; at most `limit` rows', () => {
    const result = Array.from({ length: 12 }, (_, i) => ({
      metric: { coraza_rule_id: String(800000 + i) },
      value: [1, String(i + 1)] as [number, string],
    }));
    const rows = wafTopRulesView({ status: 'success', data: { resultType: 'vector', result } });
    expect(rows).toHaveLength(10);
    expect(rows[0]).toMatchObject({ ruleId: '800011', name: 'Rule 800011', events: 12 });
  });
});
